const body = $input.first().json.body || {};

const rawText  = (body.Body || '').trim().toLowerCase();
const fromNum  = body.From || '';
const toNum    = body.To   || '';

let intent   = 'unknown';
let keywords = '';
let location = 'Remote';
let job_url  = '';

if (rawText === 'help' || rawText === 'hi' || rawText === 'hello' || rawText === 'start') {
  intent = 'help';

} else if (rawText === 'top' || rawText === 'top jobs' || rawText === 'jobs') {
  intent = 'top';
  keywords = 'AI engineer data scientist machine learning';
  location = 'Remote';

} else if (rawText.startsWith('find ') || rawText.startsWith('search ')) {
  intent = 'search';
  let query = rawText.replace(/^(find|search)\s+/, '');
  const inMatch = query.match(/\s+in\s+(.+)$/);
  if (inMatch) {
    location = inMatch[1].trim();
    keywords = query.replace(inMatch[0], '').trim();
  } else {
    keywords = query;
  }

} else if (rawText.startsWith('apply ')) {
  intent = 'apply';
  const urlMatch = rawText.match(/https?:\/\/[^\s]+/i);
  job_url = urlMatch ? urlMatch[0] : '';

} else {
  intent = 'unknown';
}

return [{ json: { intent, keywords, location, job_url, from_number: fromNum, to_number: toNum, raw_text: rawText } }];

const html        = $input.item.json.data || '';
const fromNode    = $('Parse Command').first().json;
const keywords    = fromNode.keywords;
const location    = fromNode.location;
const fromNumber  = fromNode.from_number;
const toNumber    = fromNode.to_number;

const mySkills = ['n8n','python','sql','gcp','vertex ai','machine learning','data science',
  'ai','llm','automation','data analyst','cloud','bigquery'];

const jobs = [];
const liBlocks = html.split(/<\/li>/);

for (const block of liBlocks) {
  if (!block.includes('base-card')) continue;

  const titleMatch   = block.match(/class="[^"]*base-search-card__title[^"]*"[^>]*>[\s]*([^<]+)[\s]*<\/h3>/);
  const title        = titleMatch ? titleMatch[1].trim() : null;
  if (!title) continue;

  const companyMatch = block.match(/class="[^"]*base-search-card__subtitle[^"]*"[^>]*>[\s]*(?:<[^>]+>[\s]*)*([^<]+)[\s]*<\//);
  const company      = companyMatch ? companyMatch[1].trim() : 'Unknown';

  const locMatch     = block.match(/class="[^"]*job-search-card__location[^"]*"[^>]*>[\s]*([^<]+)[\s]*<\/span>/);
  const jobLocation  = locMatch ? locMatch[1].trim() : '';

  const urlMatch     = block.match(/href="(https:\/\/[^"]*linkedin\.com\/jobs\/view\/[^"?]+)/);
  const jobUrl       = urlMatch ? urlMatch[1].split('?')[0] : '';

  const haystack     = (title + ' ' + company).toLowerCase();
  const score        = mySkills.filter(s => haystack.includes(s)).length;

  jobs.push({ title, company, location: jobLocation, job_url: jobUrl, score });
}

jobs.sort((a, b) => b.score - a.score);
const top = jobs.slice(0, 3);

let reply = '';
if (top.length === 0) {
  reply = `🔍 No jobs found for "${keywords}" in ${location}.\nTry a broader term — e.g. _find data scientist_`;
} else {
  reply = `🔍 *Top ${top.length} results for "${keywords}"*\n_(${location})_\n\n`;
  top.forEach((j, i) => {
    reply += `${i + 1}. *${j.title}*\n   _${j.company}_ • ${j.location}\n   ${j.job_url}\n\n`;
  });
  reply += `Reply *find [job title]* to search again.`;
}

return [{ json: { reply, from_number: fromNumber, to_number: toNumber } }];

const fromNode   = $input.item.json;
const fromNumber = fromNode.from_number;
const toNumber   = fromNode.to_number;
const rawText    = fromNode.raw_text || '';

const reply = [
  `❓ Didn't understand: "${rawText}"`,
  '',
  'Try:',
  '• *find AI engineer remote*',
  '• *find data scientist in Nairobi*',
  '• *top* — top jobs now',
  '• *apply https://...* — fill out a job form',
  '• *help* — see all commands'
].join('\n');

return [{ json: { reply, from_number: fromNumber, to_number: toNumber } }];

const d = $input.first().json;
const job_url    = d.job_url;
const from_number = d.from_number;
const to_number   = d.to_number;

if (!job_url) {
  return [{
    json: {
      error: 'no_url',
      request_body: null,
      reply: '❌ Please include the full URL.\nExample: *apply https://jobs.example.com/data-analyst*',
      from_number,
      to_number
    }
  }];
}

let company_name = 'Company';
let job_title = 'Data Science Position';
try {
  const urlObj = new URL(job_url);
  company_name = urlObj.hostname.replace(/^www\./, '');
  const parts = urlObj.pathname.split('/').filter(Boolean);
  if (parts.length) {
    job_title = parts[parts.length - 1]
      .replace(/[-_]/g, ' ')
      .replace(/\d+/g, '')
      .trim() || 'Data Science Position';
  }
} catch(e) {}

const request_body = JSON.stringify({ job_url, job_title, company_name });

return [{
  json: { job_url, job_title, company_name, request_body, from_number, to_number }
}];

const resp = $input.first().json;
const prev = $('Handle Apply Command').first().json;
const from_number = prev.from_number;
const to_number   = prev.to_number;

let reply;
if (resp.success) {
  reply = `✅ *Application Guide Ready!*\n\n🏢 ${resp.company || prev.company_name}\n💼 ${resp.job_title || prev.job_title}\n\n📝 ${resp.fields_count || 0} fields pre-filled\n⏱ Est. ${resp.estimated_minutes || 15} min to complete manually\n\n📊 Full guide + cover letter saved in *Application Tracker* sheet!\nYou'll get another WhatsApp with the details shortly.`;
} else {
  reply = `❌ Couldn't analyze that application page.\n\nMake sure the URL links directly to the application form (not just the job listing).\nTry: *apply https://[direct form URL]*`;
}

return [{ json: { reply, from_number, to_number } }];
